package Jpractice.loop;

public class J1115_02 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//老師的題目:迴圈執行次數為10次
//		印出i=1
//			i=2 並印出迴圈結束時的i值
		int i=1;	
		while(i<=10){
		System.out.println("i="+i);
		i++;
		}
		System.out.println("最終i值="+i);
	}

}
